// #2a9013ec8a72cee5dc3c0de5 (#3c0de5) — в списке бизнесов /admin/businesses значение колонки «שפה»
// («עברית», «אנגלית») занимает одну строку при 1440, 1280 и 1024. Кейс BIZ-LIST-001. Только чтение — @prod-safe.
import { test, expect } from '../../fixtures';

test.describe('Список бизнесов — язык в одну строку (#2a9013ec8a72cee5dc3c0de5)', () => {
  test('значение языка в одну строку при 1440 / 1280 / 1024 @desktop @prod-safe #2a9013ec8a72cee5dc3c0de5', async ({ asUser }) => {
    const page = await asUser('admin');
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto('/admin/businesses');
    await expect(page.locator('main table tbody tr').first()).toBeVisible();
    await expect(page.getByRole('columnheader', { name: 'שפה', exact: true })).toBeVisible();

    for (const width of [1440, 1280, 1024]) {
      await page.setViewportSize({ width, height: 900 });
      const cells = await page.evaluate(() => {
        const ths = [...document.querySelectorAll('main table thead th')];
        const col = ths.findIndex((th) => (th as HTMLElement).innerText.trim() === 'שפה');
        return [...document.querySelectorAll('main table tbody tr')].map((tr) => {
          const td = tr.querySelectorAll('td')[col] as HTMLElement;
          const r = document.createRange();
          r.selectNodeContents(td);
          const lines = new Set([...r.getClientRects()].filter((x) => x.width > 0).map((x) => Math.round(x.top)));
          return { text: td.innerText.trim(), lines: lines.size };
        });
      });

      expect(cells.length, `${width}: нет строк в списке`).toBeGreaterThan(0);
      expect(cells.some((c) => c.text === 'עברית'), `${width}: нет значения «עברית»`).toBe(true);
      // Источник: AC «ברוחב 1440 ערך השפה (למשל "עברית") מוצג בשורה אחת».
      expect(cells.filter((c) => c.text && c.lines !== 1), `${width}: значение языка не в одну строку`).toEqual([]);
    }
  });
});
